begin;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select ('a7100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'guardian-origin-'||n||'@example.test',now(),jsonb_build_object('name','Synthetic guardian '||n) from generate_series(1,5) n;
insert into public.families(id,name) values('a7200000-0000-4000-8000-000000000001','Synthetic provenance family');
insert into public.guardians values('a7200000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000001'),('a7200000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000002');
create function pg_temp.who(n int) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub','a7100000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','aal','aal1')::text,true)$$;
create function pg_temp.guard_cmd(a text,n int) returns jsonb language sql as $$select public.product_command('community.guardian.'||a,jsonb_build_object('family_id','a7200000-0000-4000-8000-000000000001','user_id','a7100000-0000-4000-8000-'||lpad(n::text,12,'0')),gen_random_uuid())$$;
create function pg_temp.accept_code(k text) returns jsonb language sql as $$select public.product_command('community.guardian.accept',jsonb_build_object('token',current_setting(k)),gen_random_uuid())$$;
grant execute on function pg_temp.who(int),pg_temp.guard_cmd(text,int),pg_temp.accept_code(text) to authenticated;
set local role authenticated;
select pg_temp.who(2);
select throws_ok($$select pg_temp.guard_cmd('invite',1)$$,'P0409',null,'A secondary guardian cannot invite an already-linked primary guardian');
reset role;
-- A legacy accepted offer is not evidence that it created the pre-existing link.
insert into private.guardian_offers(id,family_id,invited_by,user_id,token_hash,expires_at,accepted_at)
values('a7300000-0000-4000-8000-000000000001','a7200000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000002','a7100000-0000-4000-8000-000000000001',md5(repeat('b',48)),now()+interval '1 day',now());
set local role authenticated;
select throws_ok($$select pg_temp.guard_cmd('revoke',1)$$,'42501',null,'Legacy accepted offer cannot remove independently established guardian access');
select is((select count(*)::int from public.guardians where family_id='a7200000-0000-4000-8000-000000000001'),2,'Both independent original guardians remain');
select pg_temp.who(1);
select throws_ok($$select public.product_command('community.guardian.accept',jsonb_build_object('token',repeat('b',48)),gen_random_uuid())$$,'P0409',null,'Reaccepting a legacy offer cannot claim provenance for an existing guardian');
do $$begin perform set_config('test.origin.a',pg_temp.guard_cmd('invite',3)->>'token',true);end$$;
select pg_temp.who(2);
do $$begin perform set_config('test.origin.b',pg_temp.guard_cmd('invite',3)->>'token',true);end$$;
select pg_temp.who(3);
select set_config('test.origin.accept_key',gen_random_uuid()::text,true);
select lives_ok($$select public.product_command('community.guardian.accept',jsonb_build_object('token',current_setting('test.origin.a')),current_setting('test.origin.accept_key')::uuid)$$,'Target accepts one of two independently issued offers');
select lives_ok($$select public.product_command('community.guardian.accept',jsonb_build_object('token',current_setting('test.origin.a')),current_setting('test.origin.accept_key')::uuid)$$,'Exact-key acceptance retry recognizes the post-command family authorization hash');
select lives_ok($$select pg_temp.accept_code('test.origin.a')$$,'Retry of actual originating acceptance is unchanged');
select throws_ok($$select pg_temp.accept_code('test.origin.b')$$,'P0409',null,'Other pending invitation cannot claim an already-established link');
select pg_temp.who(2);
select lives_ok($$select pg_temp.guard_cmd('revoke',3)$$,'Other inviter can withdraw their own pending invitation');
select is((select count(*)::int from public.guardians where user_id='a7100000-0000-4000-8000-000000000003'),1,'Withdrawing unrelated pending offer preserves the accepted guardian');
select pg_temp.who(3);
select lives_ok($$select pg_temp.accept_code('test.origin.a')$$,'Pending-offer withdrawal does not invalidate the actual originating offer');
select throws_ok($$select pg_temp.accept_code('test.origin.b')$$,'P0409',null,'Withdrawn pending offer cannot be accepted');
reset role;
select is((select count(*)::int from private.guardian_link_origins),1,'Only the offer that inserted the link records provenance');
set local role authenticated;
select throws_ok($$select * from private.guardian_link_origins$$,'42501',null,'Authenticated accounts cannot read private access provenance');
select pg_temp.who(1);
select lives_ok($$select pg_temp.guard_cmd('revoke',3)$$,'Actual originating inviter can revoke its guardian link');
select is((select count(*)::int from public.guardians where user_id='a7100000-0000-4000-8000-000000000003'),0,'Origin-authorized revocation removes access');
select lives_ok($$select pg_temp.guard_cmd('revoke',3)$$,'Revocation retry safely retains the completed outcome');
reset role;
select is((select count(*)::int from private.guardian_link_origins),0,'Deleting a guardian automatically deletes its link provenance');
insert into public.guardians values('a7200000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000003');
set local role authenticated;
select throws_ok($$select pg_temp.guard_cmd('revoke',3)$$,'42501',null,'Historical originating offer cannot remove a later independently created link');
select is((select count(*)::int from public.guardians where user_id='a7100000-0000-4000-8000-000000000003'),1,'Later independent access remains intact');
do $$begin perform set_config('test.origin.d',pg_temp.guard_cmd('invite',4)->>'token',true);end$$;
reset role;
insert into public.guardians values('a7200000-0000-4000-8000-000000000001','a7100000-0000-4000-8000-000000000004');
set local role authenticated;
select pg_temp.who(4);
select throws_ok($$select pg_temp.accept_code('test.origin.d')$$,'P0409',null,'Pending invitation cannot take ownership of a link established through another process');
select pg_temp.who(1);
select lives_ok($$select pg_temp.guard_cmd('revoke',4)$$,'Pending invitation may be withdrawn after independent linkage');
select is((select count(*)::int from public.guardians where user_id='a7100000-0000-4000-8000-000000000004'),1,'Pending withdrawal preserves independently linked guardian');
do $$begin perform set_config('test.origin.e',pg_temp.guard_cmd('invite',5)->>'token',true);end$$;
select lives_ok($$select pg_temp.guard_cmd('revoke',5)$$,'Pending-only invitation can be revoked without a guardian link');
select pg_temp.who(5);
select throws_ok($$select pg_temp.accept_code('test.origin.e')$$,'P0409',null,'Pending-only revocation prevents future acceptance');
select * from finish();
rollback;
